/**
 * LMDB regressions found by the develop-vs-branch differential run (WP9 3.11.6, Layer 3, seed 20260929). Develop's
 * LmdbStore and the branch's MemoryStore return the expected result for every query below.
 */
public class LmdbDifferentialRegressionTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";
	private static final String DATE = "\"2020-01-01\"^^<http://www.w3.org/2001/XMLSchema#date>";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n"
					+ trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	/**
	 * lang(IRI) is an error, so BIND leaves ?z unbound and both VALUES rows join. Branch: ?z is never bound (the VALUES
	 * value is dropped) once :p also has a literal object; with only IRI objects the branch is correct.
	 */
	@Test
	public void bindOfErroringLangDoesNotHideValuesBindingOfSameVariable() throws Exception {
		load(":a :p :b .\n:b :p :b .\n:c :p \"01\"^^xsd:integer .\n");
		String query = "SELECT ?s ?z WHERE { ?s :p ?o . BIND(lang(?s) AS ?z)"
				+ " VALUES (?z ?o) { (UNDEF :b) (\"2020-01-01\"^^xsd:date :b) } }";
		assertEquals(List.of("s=http://ex/a z=" + DATE, "s=http://ex/a z=null", "s=http://ex/b z=" + DATE,
				"s=http://ex/b z=null"), rows(query, "s", "z"));
	}

	/**
	 * A zero-length path from a constant always matches that constant. Branch: no rows (the sameTerm constant is
	 * substituted into the path, which then hits the {@code :c :p? :c} zero-length gap).
	 */
	@Test
	public void zeroOrOnePathWithSameTermOnTheSubjectConstantMatchesZeroLength() throws Exception {
		load(":c :p :d .\n");
		assertEquals(List.of("z=http://ex/c"), rows("SELECT ?z WHERE { :c :p? ?z . FILTER(sameTerm(?z, :c)) }", "z"));
	}

	/** Branch: ValueExprEvaluationException (same root cause as ExistsSubstitutionExpressionErrorTest). */
	@Test
	public void bindErrorOnCorrelatedVariableInsideExistsLeavesVariableUnbound() throws Exception {
		load(":b :q :a .\n");
		String query = "SELECT ?o WHERE { ?o :q ?z FILTER EXISTS { ?o :q ?y . BIND(?o + 1 AS ?s) } }";
		assertEquals(List.of("o=http://ex/b"), rows(query, "o"));
	}

	/**
	 * GRAPH ?g cannot match a literal. Branch: ClassCastException LmdbLiteral -> Resource once {@code ?z :p ?g} binds
	 * ?g = "a" ahead of the nested GRAPH patterns. Expected: the empty-group branch gives one group with count 0.
	 */
	@Test
	public void graphVariableBoundToLiteralDoesNotMatch() throws Exception {
		load(":b :p \"a\"^^xsd:string .\n");
		String query = "SELECT ?s (COUNT(DISTINCT ?y) AS ?agg) WHERE { { } UNION { GRAPH :g { GRAPH ?g { ?z :p ?s . } }"
				+ " OPTIONAL { } } ?g ^:p ?z . } GROUP BY ?s";
		assertEquals(List.of("s=null agg=\"0\"^^<http://www.w3.org/2001/XMLSchema#integer>"),
				rows(query, "s", "agg"));
	}

	/**
	 * GRAPH :g names no graph in the store, so {@code ?x :q* ?y} inside it has no solutions (both variables are free
	 * inside the GRAPH pattern). Branch: one row once the disjunctive filter is present (the outer ?x is pushed into
	 * the zero-length path); without the filter the branch correctly returns nothing.
	 */
	@Test
	public void zeroLengthPathInsideAbsentNamedGraphDoesNotMatchTheOuterBinding() throws Exception {
		load(":b :p \"1.0e0\"^^xsd:double .\n");
		String query = "SELECT ?x ?y WHERE { ?x :p ?s . GRAPH :g { ?x :q* ?y . } FILTER(?y = ?x || EXISTS { }) }";
		assertEquals(List.of(), rows(query, "x", "y"));
	}

	/**
	 * {@code new LmdbStore(dir)} (default config: triple indexes null) cannot be reopened: ValueStore.initTermIndexes
	 * copies the null config value over the loaded triple-indexes property before TripleStore validates it ("triple-
	 * indexes missing in store.properties file"). The branch's term-index persistence fix does not cover this; develop
	 * fails the same reopen on the triple-term indexes instead.
	 */
	@Test
	public void storeCreatedWithDefaultConfigCanBeReopened() throws Exception {
		repository.shutDown();
		File dir = new File(dataDir, "default-config");
		repository = new SailRepository(new LmdbStore(dir));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(Values.iri("http://ex/a"), Values.iri("http://ex/p"), Values.literal("x"));
		}
		repository.shutDown();
		repository = new SailRepository(new LmdbStore(dir));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			assertEquals(1, conn.size());
		}
	}
}
